 useEffect(()=>{if(!running)return;const timer=window.setTimeout(()=>{if(timeLeft<=1){if(phase==="round"){const hasNext=currentRound<settings.totalRounds;beep(430,3);if(!hasNext){endRoundFlash(false);setRunning(false);setPhase("round");setActiveExercise(null);setCurrentRound(1);setTimeLeft(settings.roundSeconds);showMessage("Sesión terminada.")}else if(settings.activityEnabled&&(settings.activityReplaceRest||settings.activityPlacement==="before-rest")){startActivity(settings.activityReplaceRest?"next-round":"rest",true)}else if(settings.activityEnabled&&settings.activityPlacement==="during-rest")startRest(true,true);else startRest(false,true)}else if(phase==="activity"){beep(1320,2);if(activityNext==="rest")startRest(false);else startRound(activityNext==="next-round")}else if(settings.activityEnabled&&!settings.activityReplaceRest&&settings.activityPlacement==="after-rest")startActivity("next-round");else startRound(true)}else{if(phase==="rest"&&activeExercise&&timeLeft<=settings.restSeconds-activeExercise.seconds+1)setActiveExercise(null);if(timeLeft===30||timeLeft===10||timeLeft<=5)beep(phase==="round"?850:phase==="activity"||activeExercise?1120:680,timeLeft<=3?2:1);setTimeLeft(value=>value-1)}},1000);return()=>window.clearTimeout(timer)},[activeExercise,activityNext,beep,currentRound,endRoundFlash,phase,running,settings.activityEnabled,settings.activityPlacement,settings.activityReplaceRest,settings.restSeconds,settings.roundSeconds,settings.totalRounds,showMessage,startActivity,startRest,startRound,timeLeft]);
 const toggleTimer=()=>{if(running){setRunning(false);return}if(phase==="round"&&timeLeft===settings.roundSeconds&&currentRound===1&&settings.activityEnabled&&settings.activityBeforeFirstRound){setRunning(true);startActivity("start-round");return}if(phase==="round"&&timeLeft===settings.roundSeconds){beep(980,2);startFlash("green",1900)}else beep(760);setRunning(true)},skipToNextRound=()=>{setActiveExercise(null);if(currentRound>=settings.totalRounds){setRunning(false);setPhase("round");setCurrentRound(1);setTimeLeft(settings.roundSeconds);showMessage("Temporizador reiniciado.");return}if(performRotation()){setPhase("round");setCurrentRound(value=>value+1);setTimeLeft(settings.roundSeconds);beep(980,2);startFlash("green",1900)}},resetTimer=()=>{setRunning(false);setPhase("round");setActiveExercise(null);setActivityNext("next-round");setCurrentRound(1);setTimeLeft(settings.roundSeconds);clearFlashTimers();setFlash(null)};
