 const startDrag=(event:React.PointerEvent,kind:"cube"|"group",id:string,x:number,y:number,width:number)=>{const target=event.target as HTMLElement;if(target.closest("button,input,select")&&!target.closest("[data-drag-handle]"))return;const rect=boardRef.current?.getBoundingClientRect();if(!rect)return;event.preventDefault();setDrag({kind,id,width,offsetX:event.clientX-rect.left-x,offsetY:event.clientY-rect.top-y})},autoArrange=()=>{let cursorX=24,cursorY=28;setGroups(items=>items.map(group=>{const width=groupWidth(group.members.length);if(cursorX+width>BOARD_WIDTH-8){cursorX=24;cursorY+=155}const arranged={...group,x:cursorX,y:cursorY};cursorX+=width+12;return arranged}));setCubes(items=>items.map(cube=>{if(groupedIds.has(cube.id))return cube;if(cursorX+CUBE_WIDTH>BOARD_WIDTH-8){cursorX=24;cursorY+=142}const arranged={...cube,x:cursorX,y:cursorY};cursorX+=CUBE_WIDTH+12;return arranged}))},beginNote=(id:string)=>{const cube=cubeMap.get(id);if(!cube)return;setEditing(id);setNoteDraft(cube.note)},saveNote=()=>{if(editing)setCubes(items=>items.map(cube=>cube.id===editing?{...cube,note:noteDraft.trim().slice(0,40)}:cube));setEditing(null)};
