function BoardClock({phase,currentRound,totalRounds,timeLeft,duration,running,exercise,onToggle,onReset}:{phase:TimerPhase;currentRound:number;totalRounds:number;timeLeft:number;duration:number;running:boolean;exercise:OrganizerExercise|null;onToggle:()=>void;onReset:()=>void}){const activity=phase==="activity"||Boolean(exercise),resting=phase==="rest"&&!exercise,displayTime=phase==="rest"&&exercise?Math.max(0,timeLeft-(duration-exercise.seconds)):timeLeft,progressDuration=activity?(exercise?.seconds||duration):duration,urgent=displayTime<=5;return <section className={`mt-3 overflow-hidden rounded-2xl border p-3 transition sm:p-4 ${activity?"border-amber-300/40 bg-[radial-gradient(circle_at_center,rgba(251,191,36,.18),transparent_70%),rgba(245,158,11,.08)]":resting?"border-sky-300/30 bg-sky-500/10":"border-emerald-300/20 bg-emerald-500/[.07]"}`}><div className="flex flex-col items-stretch gap-4 sm:flex-row sm:items-center"><div className="min-w-[150px]"><p className={`eyebrow ${activity?"text-amber-300":resting?"text-sky-300":"text-emerald-300"}`}>{activity?"Actividad aleatoria":resting?"Descanso":"Round en curso"}</p><b className="mt-1 block text-sm">{activity?`Antes del round ${phase==="activity"&&currentRound===1?currentRound:Math.min(totalRounds,currentRound+1)}`:resting?`Antes del round ${Math.min(totalRounds,currentRound+1)}`:`Round ${currentRound} de ${totalRounds}`}</b></div>{activity&&exercise?<div className="min-w-0 flex-1 text-center"><strong className="block text-2xl font-black uppercase tracking-tight text-amber-100 sm:text-4xl">{exercise.label}</strong><span className="mt-1 inline-flex rounded-full border border-amber-200/30 bg-amber-300/15 px-4 py-1 text-sm font-black text-amber-100">{repetitionLabel(exercise.repetitions,true)}</span></div>:<div className="flex-1"/>}<div className="flex min-w-[170px] items-center justify-center gap-3 sm:justify-end"><strong className={`font-mono text-4xl font-black tracking-tight sm:text-5xl ${urgent?"animate-pulse text-rose-300":activity?"text-amber-200":resting?"text-sky-200":"text-white"}`}>{formatClock(displayTime)}</strong></div><div className="flex justify-center gap-2"><button type="button" onClick={onToggle} className={`tool-button ${running?"text-amber-200":resting?"text-sky-100":"text-emerald-100"}`}>{running?<CirclePause/>:<CirclePlay/>}{running?"Pausar":"Continuar"}</button><button type="button" onClick={onReset} className="tool-button" title="Reiniciar temporizador"><TimerReset/>Reiniciar</button></div></div><div className="mt-3 h-2.5 overflow-hidden rounded-full bg-black/30"><div className={`h-full rounded-full transition-all duration-700 ${urgent?"bg-rose-400":activity?"bg-amber-300":resting?"bg-sky-400":"bg-emerald-400"}`} style={{width:`${Math.max(0,Math.min(100,displayTime/Math.max(1,progressDuration)*100))}%`}}/></div><div className="mt-2 flex justify-between gap-3 text-[9px] font-bold uppercase tracking-wider text-slate-500"><span>{running?"Cronómetro activo":"Cronómetro pausado"}</span><span>{activity?"Amarillo: actividad · pitidos de acción":resting?"Azul: recuperación":"Verde: inicio · Rojo: final"}</span></div></section>}
