function MiniMetric({value,label}:{value:number|string;label:string}){return <span className="rounded-xl border border-white/[.07] bg-black/20 p-2"><b className="block text-sm text-white">{value}</b><small className="text-[8px] font-black uppercase text-slate-500">{label}</small></span>}
function Status({icon:Icon,value,label}:{icon:typeof UserRound;value:number;label:string}){return <span className="flex min-h-12 items-center gap-3 rounded-2xl border border-white/10 bg-black/20 px-4"><Icon className="h-4 w-4 text-cyan-300"/><span><b className="block leading-none">{value}</b><small className="text-[9px] font-black uppercase text-slate-500">{label}</small></span></span>}
function NoteDialog({name,value,onChange,onSave,onClose}:{name:string;value:string;onChange:(value:string)=>void;onSave:()=>void;onClose:()=>void}){return <div className="fixed inset-0 z-[120] grid place-items-center bg-black/75 p-4 backdrop-blur-md" role="dialog" aria-modal="true"><form onSubmit={event=>{event.preventDefault();onSave()}} className="w-full max-w-md rounded-[1.75rem] border border-cyan-300/20 bg-[#0c111a] p-5"><div className="flex justify-between"><div><p className="eyebrow text-cyan-300">Nota del cubo</p><h2 className="text-xl font-black">{name}</h2></div><button type="button" onClick={onClose} className="neon-icon"><X/></button></div><input autoFocus value={value} onChange={event=>onChange(event.target.value)} maxLength={40} placeholder="Ej. 1, capitán…" className="config-input mt-5 min-h-12 w-full"/><div className="mt-5 grid grid-cols-2 gap-2"><button type="button" onClick={onClose} className="tool-button">Cancelar</button><button type="submit" className="primary-button">Guardar nota</button></div></form></div>}
